ecc_agent_script_file.script:
(function() {
    // Expect email and password as inputs
    var result = {
        success: false,
        message: '',
        student: null
    };

    if (!input || !input.email || !input.password) {
        result.success = false;
        result.message = 'Please enter email and password';
        return result;
    }

    var gr = new GlideRecord('x_1909965_almaconn_student');
    gr.addQuery('u_email', input.email);      // adjust field name: u_email or email
    gr.addQuery('u_password', input.password); // plain comparison for demo; not secure
    gr.query();

    if (gr.next()) {
        result.success = true;
        result.message = 'Login successful';
        result.student = {
            sys_id: gr.getUniqueValue(),
            name: gr.u_student_name + '' // adjust field name
        };
    } else {
        result.success = false;
        result.message = 'Incorrect email or password';
    }

    return result;
})();
